                    ids.append(i)
        elif isinstance(coords, dict):
            for k in coords.keys():
                if k != depot:
                    ids.append(k)
        elif coords is not None:
            n = len(coords)
            for i in range(n):
                if i != depot:
                    ids.append(i)
        else:
            n = get(instance, "n", None)
            if n is None:
                n = get(instance, "num_customers", 0)
            for i in range(1, n + 1):
                if i != depot:
                    ids.append(i)
        ids = list(set(ids))
        ids.sort()
        return ids

    customers = all_customer_ids()

    def dist2(a, b):
        ca = coord_of(a)
        cb = coord_of(b)
        if ca is None or cb is None:
            return 0
        dx = ca[0] - cb[0]
        dy = ca[1] - cb[1]
        return dx * dx + dy * dy

    if coords is not None:
        d0 = coord_of(depot)
        if d0 is None:
            customers = sorted(customers)
        else:
            def key_fn(i):
                c = coord_of(i)
                if c is None:
                    return (4, 0, i)
                dx = c[0] - d0[0]
                dy = c[1] - d0[1]
                q = 0 if (dy >= 0 and dx >= 0) else 1 if (dy >= 0 and dx < 0) else 2 if (dy < 0 and dx < 0) else 3
                return (q, abs(dx) + abs(dy), dist2(depot, i), i)
            customers = sorted(customers, key=key_fn)
    else:
        customers = sorted(customers, key=lambda i: (-demand_of(i), i))

    unrouted = customers[:]
    routes = []

    while unrouted:
        start = unrouted[0]
        for c in unrouted[1:]:
            dc = demand_of(c)
            ds = demand_of(start)
            if dc > ds or (dc == ds and c < start):
                start = c
        route = [start]
        load = demand_of(start)
        unrouted.remove(start)
        last = start

        while True:
            best = None
            best_key = None
            for c in unrouted:
                dc = demand_of(c)
                if load + dc > capacity:
                    continue
                k = (dist2(last, c), dc, c)
                if best is None or k < best_key:
                    best = c
                    best_key = k
            if best is None:
                break
            route.append(best)
            load += demand_of(best)
            unrouted.remove(best)
            last = best
        routes.append(route)

    def route_load(r):
        s = 0
        for x in r:
            s += demand_of(x)
        return s

    def route_length(r):
        if not r:
            return 0
        total = dist2(depot, r[0]) + dist2(r[-1], depot)
        for a, b in zip(r, r[1:]):
            total += dist2(a, b)
        return total

    improved = True
    passes = 0
    while improved and passes < 25:
        improved = False
        passes += 1

        for idx in range(len(routes)):
            r = routes[idx]
            n = len(r)
            if n < 4:
                continue
            best_gain = 0
            best_i = -1
            best_j = -1
            for i in range(n - 1):
                a = depot if i == 0 else r[i - 1]
                b = r[i]
                for j in range(i + 2, n):
                    c = r[j]
                    d = depot if j == n - 1 else r[j + 1]
                    gain = (dist2(a, b) + dist2(c, d)) - (dist2(a, c) + dist2(b, d))
                    if gain > best_gain:
                        best_gain = gain
                        best_i = i
                        best_j = j
            if best_gain > 0:
                routes[idx] = r[:best_i] + list(reversed(r[best_i:best_j + 1])) + r[best_j + 1:]
                improved = True

        if improved:
            continue

        for i in range(len(routes)):
            if improved:
                break
            ri = routes[i]
            for j in range(len(routes)):
                if i == j:
                    continue
                rj = routes[j]
                load_j = route_load(rj)
                best_move = None
                best_delta = 0
                for a_idx, a in enumerate(ri):
                    da = demand_of(a)
                    if load_j + da > capacity:
                        continue
                    prev_a = depot if a_idx == 0 else ri[a_idx - 1]
                    next_a = depot if a_idx == len(ri) - 1 else ri[a_idx + 1]
                    remove_cost = dist2(prev_a, a) + dist2(a, next_a) - dist2(prev_a, next_a)
                    for b_pos in range(len(rj) + 1):
                        prev_b = depot if b_pos == 0 else rj[b_pos - 1]
                        next_b = depot if b_pos == len(rj) else rj[b_pos]
                        add_cost = dist2(prev_b, a) + dist2(a, next_b) - dist2(prev_b, next_b)
                        delta = remove_cost + add_cost
                        if delta < best_delta:
                            best_delta = delta
                            best_move = (a_idx, b_pos)
                if best_move is not None:
                    a_idx, b_pos = best_move
                    node = ri.pop(a_idx)
                    if b_pos > len(rj):
                        b_pos = len(rj)
                    rj.insert(b_pos, node)
                    if not ri:
                        routes.pop(i)
                    routes[j if j < i else j - (1 if not ri and j > i else 0)] = rj
                    improved = True
                    break

    seen = set()
    final_routes = []
    for r in routes:
        nr = []
        load = 0
        for c in r:
            if c == depot or c in seen:
                continue
            dc = demand_of(c)
            if load + dc <= capacity:
                nr.append(c)
                seen.add(c)
                load += dc
        if nr:
            final_routes.append(nr)

    missing = []
    for c in customers:
        if c not in seen:
            missing.append(c)

    for c in missing:
        placed = False
        dc = demand_of(c)
        for r in final_routes:
            if route_load(r) + dc <= capacity:
                r.append(c)
                placed = True
                break
        if not placed:
            final_routes.append([c])

    return final_routes
